"""Nov13 corrective acceptance. Synthetic records, real Chromium/WebKit, no external writes."""
import importlib.util, unittest, json, base64, os
from pathlib import Path
spec=importlib.util.spec_from_file_location('baseline',Path(__file__).with_name('qa-20261112.py'))
base=importlib.util.module_from_spec(spec);spec.loader.exec_module(base)
OUT=Path('var/qa-20261113');OUT.mkdir(parents=True,exist_ok=True)
PNG=base64.b64decode('iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAwMCAO+a8RQAAAAASUVORK5CYII=')
class Consolidated(unittest.TestCase):
 setUpClass=classmethod(base.Remediation.setUpClass.__func__)
 tearDownClass=classmethod(base.Remediation.tearDownClass.__func__)
 state=base.Remediation.state
 def setUp(self):
  self.context=self.browser.new_context(viewport={'width':810,'height':1080});self.page=self.context.new_page();self.errors=[];self.writes=[]
  self.page.on('pageerror',lambda e:self.errors.append(str(e)))
  self.page.on('request',lambda r:self.writes.append(r.url) if r.method not in ['GET','HEAD'] else None)
 def tearDown(self):
  self.assertEqual(self.errors,[]);self.assertEqual(self.writes,[]);self.context.close()
 def nav(self,name):
  self.page.locator('#profile-nav,#athlete-resource-nav').get_by_role('link',name=name,exact=True).click()
 def basic(self,sport='lacrosse'):
  p=self.page;p.goto(base.BASE+'/build?new=1');p.wait_for_selector('#athlete-basics:not([disabled])');p.locator('#nickname').fill('Casey Demo');p.locator('#sport').select_option(sport);p.locator('#guardian').check();p.locator('#club-team').fill('Family team · synthetic');p.get_by_role('button',name='Save athlete profile').click();p.wait_for_selector('#show-tryouts');return self.state()['active']
 def follow(self,category):
  choices=self.page.locator('#content-choices-'+category);choices.wait_for();choices.locator('summary').click()
  for cb in choices.locator('input:not([disabled])').all():cb.check()
  choices.locator('summary').click()
 def screenshot(self,name):self.page.screenshot(path=str(OUT/f'{base.ENGINE}-{name}.png'),full_page=True)
 def test_01_complete_guided_journey_with_shared_references(self):
  p=self.page;p.goto(base.BASE+'/sports/lacrosse');self.assertGreaterEqual(p.locator('.directory-records>article').count(),13);p.get_by_role('link',name='Clubs & Teams',exact=True).click();p.wait_for_selector('.result-count');self.assertGreaterEqual(p.locator('.directory-records>article').count(),13)
  p.goto(base.BASE+'/my-pathway?view=family');p.get_by_role('link',name='+ Add athlete',exact=True).click();p.wait_for_selector('#athlete-journey');w=p.locator('#athlete-journey');w.get_by_label('Search club or Add Your Own',exact=True).fill('Denver Elite');self.screenshot('guided-club-ipad')
  p.get_by_role('button',name='Next →',exact=True).click();w.get_by_label('Program or team',exact=True).fill('Family-entered team · synthetic');p.get_by_role('button',name='Next →',exact=True).click();w.get_by_label('Season label',exact=True).fill('Fall 2026');p.get_by_role('button',name='Next →',exact=True).click();w.get_by_label('Age group / division',exact=True).fill('U16');p.get_by_role('button',name='Next →',exact=True).click();w.get_by_label('Athlete name',exact=True).fill('Casey Demo');w.get_by_label('Position / event',exact=True).fill('Attack');w.get_by_label('Goals',exact=True).fill('Improve passing');w.get_by_label('I am the parent / guardian managing this athlete',exact=True).check();p.get_by_role('button',name='Next →',exact=True).click();w.get_by_label('Schedule setup',exact=True).select_option('manual');self.screenshot('guided-schedule-ipad');p.locator('#athlete-journey').get_by_role('button',name='Save athlete profile',exact=True).click();p.wait_for_selector('#show-tryouts',state='attached')
  athlete=self.state()['active'];self.assertEqual(len(self.state()['profiles']),1);self.assertNotIn('recruiting',self.state()['profiles'][0]['modules']);self.assertEqual(self.state()['profiles'][0]['seasonLabel'],'Fall 2026');self.assertEqual(self.state()['profiles'][0]['ageGroup'],'U16');self.assertTrue(p.locator('#schedule-editor').evaluate('(e)=>e.open'))
  p.locator('#plan-title').fill('Family recurring practice');p.locator('#plan-start').fill('2026-11-16');p.locator('#plan-repeat').select_option('weekly');p.locator('#plan-until').fill('2026-11-30');p.get_by_role('button',name='Add to schedule',exact=True).click();p.wait_for_selector('#schedule-list article');self.assertEqual(p.locator('#schedule-list article').count(),3)
  p.get_by_role('button',name='Add Game/Meet/Tournament',exact=True).click();p.locator('#plan-title').fill('Family tournament');p.locator('#plan-kind').select_option('tournament');p.locator('#plan-start').fill('2026-11-19');p.get_by_role('button',name='Add to schedule',exact=True).click();p.wait_for_function('()=>JSON.parse(localStorage.getItem("arenaPathway.v2")).profiles[0].plans.length===2');event=self.state()['profiles'][0]['plans'][1]['id'];p.locator('#schedule-list article').filter(has_text='Family tournament').get_by_role('button',name='Log stats',exact=True).click();self.assertEqual(p.locator('#record-event').input_value(),event);p.locator('#metric-Goals').fill('2');p.get_by_role('button',name='Save game / meet record',exact=True).click();p.wait_for_selector('#stats .record');self.assertFalse(p.locator('#stats-editor').evaluate('(e)=>e.open'))
  self.nav('Media');p.get_by_role('button',name='Add Media',exact=True).click();p.locator('#media-upload').set_input_files({'name':'fixture.png','mimeType':'image/png','buffer':PNG});p.locator('#media-caption').fill('Synthetic tournament highlight');p.locator('#media-event').select_option(event);p.get_by_role('button',name='Save media',exact=True).click();p.wait_for_selector('.family-media-gallery img');self.assertFalse(p.locator('#media-editor').evaluate('(e)=>e.open'))
  self.nav('My Feed');self.follow('news');self.assertEqual(p.locator('#my-feed .content-items article').count(),3);self.assertEqual(p.locator('#my-feed .source-chips button').count(),4);p.locator('#my-feed .source-chips button').nth(1).click();self.assertEqual(p.locator('#my-feed .content-items article').count(),1);p.locator('#my-feed .source-chips button').first.click();self.screenshot('journey-feed-ipad')
  self.nav('Development');self.follow('development');self.assertGreater(p.locator('#camps .content-items article').count(),0);p.get_by_label('Training category',exact=True).select_option('planning');self.assertIn('Athlete Development Model',p.locator('#camps .content-items').inner_text())
  self.nav('Community');p.get_by_role('link',name='Open Community resources').click();p.wait_for_selector('.public-community');self.assertEqual(p.locator('.community-category').count(),6);self.assertEqual(self.state()['active'],athlete)
  p.goto(base.BASE+'/my-ap?scenario=local&section=calendar');p.wait_for_selector('#platform-calendar');p.get_by_label('Calendar date',exact=True).fill('2026-11-19');p.get_by_label('Calendar date',exact=True).press('Tab');p.get_by_role('button',name='Week',exact=True).click();activity=p.locator('#platform-calendar .ap-activity').filter(has_text='Family tournament');activity.wait_for();activity.get_by_role('button',name='Details').click();p.get_by_role('link',name='Edit athlete schedule').click();p.wait_for_selector('.originating-event');self.assertEqual(self.state()['active'],athlete);self.assertEqual(len(self.state()['profiles'][0]['plans']),2)
  self.nav('Recruiting');p.wait_for_selector('#college-research');p.get_by_label('Program division',exact=True).select_option('NCAA D1');p.get_by_label('Program gender',exact=True).select_option('Men’s');p.get_by_label('Search institution',exact=True).fill('Denver');self.assertGreater(p.locator('.research-results article').count(),0);p.locator('.research-results button[data-save]').first.click();self.assertEqual(len(self.state()['profiles'][0]['saved']),1);self.assertEqual(p.get_by_label('Search institution',exact=True).input_value(),'Denver');self.assertNotIn('recruiting',self.state()['profiles'][0]['modules'])
  p.goto(base.BASE+'/locked-in-demo');self.assertIn('Non-operational',p.locator('main').inner_text());self.assertEqual(p.locator('main input,main form').count(),0);self.assertEqual(self.state()['active'],athlete)
  (OUT/f'{base.ENGINE}-journey.json').write_text(json.dumps(self.state(),indent=2))
 def test_02_records_before_editors_and_preserved_after_edit(self):
  athlete=self.basic();p=self.page;self.nav('Schedule');self.assertFalse(p.locator('#schedule-editor').evaluate('(e)=>e.open'));p.get_by_role('button',name='Add Recurring Practice',exact=True).click();self.assertEqual(p.locator('#plan-repeat').input_value(),'weekly');p.locator('#plan-title').fill('Practice');p.locator('#plan-start').fill('2026-11-16');p.locator('#plan-until').fill('2026-11-30');p.get_by_role('button',name='Add to schedule',exact=True).click();p.wait_for_selector('#schedule-list article');plan=self.state()['profiles'][0]['plans'][0]
  p.get_by_role('button',name='Edit this occurrence',exact=True).first.click();p.locator('#plan-title').fill('Moved practice');p.locator('#plan-start').fill('2026-11-17');p.locator('#plan-end').fill('2026-11-17');p.get_by_role('button',name='Save this occurrence',exact=True).click();self.assertEqual(self.state()['profiles'][0]['plans'][0]['id'],plan['id']);p.goto(base.BASE+'/build');p.wait_for_selector('#athlete-basics:not([disabled])');self.assertEqual(p.locator('#athlete-journey').count(),0);p.locator('#nickname').fill('Edited Casey');p.get_by_role('button',name='Save athlete profile').click();p.wait_for_selector('#show-tryouts');self.assertEqual(self.state()['active'],athlete);self.assertEqual(len(self.state()['profiles']),1);self.assertEqual(self.state()['profiles'][0]['plans'][0]['id'],plan['id'])
  for name,editor in [('Stats','#stats-editor'),('Media','#media-editor')]:self.nav(name);self.assertFalse(p.locator(editor).evaluate('(e)=>e.open'))
 def test_03_feed_loading_failure_retry_and_subscription_preservation(self):
  self.basic();p=self.page;self.nav('My Feed');self.follow('news');before=self.state();pending=[];p.route('**/api/reviewed-content',lambda route:pending.append(route));p.reload();p.wait_for_selector('#show-tryouts',state='attached');self.nav('My Feed');p.wait_for_selector('#my-feed [aria-busy=true]');self.assertTrue(pending);pending[0].fulfill(status=503,body='Unavailable');p.wait_for_selector('#my-feed button:text-is("Retry content")');self.assertEqual(self.state(),before);p.unroute('**/api/reviewed-content');p.get_by_role('button',name='Retry content',exact=True).first.click();p.wait_for_selector('#my-feed .content-items article');self.assertEqual(p.locator('#my-feed .content-items article').count(),3);self.assertEqual(self.state(),before)
 def test_04_public_research_filters_draft_gates_and_source_links(self):
  p=self.page;p.goto(base.BASE+'/recruiting');p.wait_for_selector('#college-research');self.assertEqual(p.evaluate('JSON.parse(localStorage.getItem("arenaPathway.v2")||"null")?.profiles?.length||0'),0);p.get_by_label('Program gender',exact=True).select_option('Women’s');self.assertGreater(p.locator('.research-results article').count(),0);p.get_by_label('Program division',exact=True).select_option('NJCAA');self.assertIn('0 reviewed matching programs',p.locator('.research-results').inner_text());p.locator('[aria-label="Recruiting discovery"]').get_by_role('button',name='Outreach Drafts',exact=True).click();self.assertEqual(p.get_by_label('Parent outreach draft').count(),0)
  self.basic();p.goto(base.BASE+'/recruiting');p.wait_for_selector('#college-research');p.locator('[aria-label="Recruiting discovery"]').get_by_role('button',name='Outreach Drafts',exact=True).click();self.assertIn('age16+',p.locator('.research-results').inner_text());self.assertEqual(p.get_by_label('Parent outreach draft').count(),0);self.assertNotIn('recruiting',self.state()['profiles'][0]['modules'])
 def test_05_optional_siem_tour_colors_and_privacy(self):
  p=self.page;p.goto(base.BASE+'/my-ap?scenario=family');p.wait_for_selector('.ap-activity');self.assertFalse(p.locator('#siem-tour').evaluate('(e)=>e.open'));colors=p.locator('.ap-activity[data-athlete]').evaluate_all('(xs)=>Object.fromEntries(xs.map(x=>[x.dataset.athlete,[...x.classList].find(c=>/^ap-athlete-/.test(c))]))');self.assertTrue(colors)
  p.locator('#platform-settings>summary').click();p.get_by_role('button',name='Start guided tour',exact=True).click();p.wait_for_selector('#siem-tour[open]');self.assertIn('Step 1 of 6',p.locator('#siem-tour').inner_text());p.locator('#siem-tour').get_by_role('button',name='Next',exact=True).click();self.assertIn('Consolidated calendar',p.locator('#siem-tour').inner_text());p.locator('#siem-tour').get_by_role('button',name='Back',exact=True).click();self.assertIn('Step 1 of 6',p.locator('#siem-tour').inner_text());p.locator('#siem-tour').get_by_role('button',name='Restart',exact=True).click()
  for _ in range(4):p.locator('#siem-tour').get_by_role('button',name='Next',exact=True).click()
  self.assertIn('Slack',p.locator('#siem-tour').inner_text());p.locator('#siem-tour').get_by_role('button',name='Skip',exact=True).click();self.assertFalse(p.locator('#siem-tour').evaluate('(e)=>e.open'));self.assertTrue(p.locator('#platform-settings>summary').evaluate('(e)=>document.activeElement===e'))
  for item in p.locator('.ap-message[data-athlete]').all():
   who=item.get_attribute('data-athlete')
   if who in colors:self.assertIn(colors[who],item.get_attribute('class'))
  p.locator('#platform-settings>summary').click();p.get_by_role('button',name='Start guided tour',exact=True).click()
  for _ in range(5):p.locator('#siem-tour').get_by_role('button',name='Next',exact=True).click()
  self.assertIn('Step 6 of 6',p.locator('#siem-tour').inner_text());p.locator('#siem-tour').get_by_role('button',name='Finish',exact=True).click();self.assertFalse(p.locator('#siem-tour').evaluate('(e)=>e.open'))
  p.reload();p.wait_for_selector('.ap-feed');self.assertFalse(p.locator('#siem-tour').evaluate('(e)=>e.open'))
 def test_06_responsive_editorial_and_independent_locked_preview(self):
  self.basic('basketball');p=self.page;self.nav('My Feed');self.follow('news');self.assertGreater(p.locator('#my-feed time[datetime]').count(),0);self.assertEqual(p.locator('#my-feed .editorial-card>img').count(),0)
  for name,w,h in [('desktop',1440,900),('ipad',810,1080),('iphone',390,844)]:
   p.set_viewport_size({'width':w,'height':h});self.assertFalse(p.evaluate('document.documentElement.scrollWidth>innerWidth+1'));p.locator('#my-feed').screenshot(path=str(OUT/f'{base.ENGINE}-editorial-{name}.png'))
